<!DOCTYPE html>
<html lang="zh">
<head>
<meta charset="UTF-8">
<title>鹈鹕骑自行车 - 海边动画</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { overflow: hidden; background: #87CEEB; }
canvas { display: block; }
</style>
</head>
<body>
<canvas id="c"></canvas>
<script>
const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d');
let W, H;
function resize() {
  W = canvas.width = window.innerWidth;
  H = canvas.height = window.innerHeight;
}
resize();
window.addEventListener('resize', resize);

let time = 0;
const speed = 2;

// Clouds
const clouds = [];
for (let i = 0; i < 8; i++) {
  clouds.push({
    x: Math.random() * W * 2,
    y: H * 0.05 + Math.random() * H * 0.2,
    w: 80 + Math.random() * 120,
    h: 30 + Math.random() * 30,
    speed: 0.3 + Math.random() * 0.5
  });
}

// Birds in sky
const birds = [];
for (let i = 0; i < 5; i++) {
  birds.push({
    x: Math.random() * W,
    y: H * 0.08 + Math.random() * H * 0.15,
    speed: 1 + Math.random() * 2,
    phase: Math.random() * Math.PI * 2
  });
}

// Waves
const waveLines = 5;

// Palm trees
const palms = [];
for (let i = 0; i < 6; i++) {
  palms.push({
    x: i * W / 3 + Math.random() * W / 4,
    scale: 0.7 + Math.random() * 0.5
  });
}

// Road markings
const markings = [];
for (let i = 0; i < 20; i++) {
  markings.push({ x: i * 120 });
}

function drawSky() {
  const grad = ctx.createLinearGradient(0, 0, 0, H * 0.45);
  grad.addColorStop(0, '#1a73e8');
  grad.addColorStop(0.4, '#4fc3f7');
  grad.addColorStop(0.7, '#81d4fa');
  grad.addColorStop(1, '#b3e5fc');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H * 0.45);
}

// Sun
function drawSun() {
  const sx = W * 0.82, sy = H * 0.1, r = 45;
  // Glow
  const glow = ctx.createRadialGradient(sx, sy, r * 0.5, sx, sy, r * 3);
  glow.addColorStop(0, 'rgba(255,235,59,0.4)');
  glow.addColorStop(1, 'rgba(255,235,59,0)');
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(sx, sy, r * 3, 0, Math.PI * 2);
  ctx.fill();
  // Sun rays
  ctx.save();
  ctx.translate(sx, sy);
  ctx.rotate(time * 0.005);
  for (let i = 0; i < 12; i++) {
    ctx.rotate(Math.PI / 6);
    ctx.beginPath();
    ctx.moveTo(0, r + 5);
    ctx.lineTo(-4, r + 25);
    ctx.lineTo(4, r + 25);
    ctx.closePath();
    ctx.fillStyle = '#FDD835';
    ctx.fill();
  }
  ctx.restore();
  // Sun body
  ctx.beginPath();
  ctx.arc(sx, sy, r, 0, Math.PI * 2);
  ctx.fillStyle = '#FFD600';
  ctx.fill();
  ctx.beginPath();
  ctx.arc(sx, sy, r - 5, 0, Math.PI * 2);
  ctx.fillStyle = '#FFEB3B';
  ctx.fill();
}

function drawClouds() {
  clouds.forEach(c => {
    c.x -= c.speed;
    if (c.x + c.w < -100) c.x = W + 100;
    ctx.fillStyle = 'rgba(255,255,255,0.9)';
    ctx.beginPath();
    ctx.ellipse(c.x, c.y, c.w * 0.5, c.h * 0.5, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(c.x - c.w * 0.25, c.y + 5, c.w * 0.35, c.h * 0.4, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(c.x + c.w * 0.25, c.y + 3, c.w * 0.38, c.h * 0.42, 0, 0, Math.PI * 2);
    ctx.fill();
  });
}

function drawBirds() {
  birds.forEach(b => {
    b.x -= b.speed;
    if (b.x < -30) b.x = W + 30;
    const wing = Math.sin(time * 0.08 + b.phase) * 8;
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(b.x - 10, b.y + wing);
    ctx.quadraticCurveTo(b.x - 3, b.y - 5, b.x, b.y);
    ctx.quadraticCurveTo(b.x + 3, b.y - 5, b.x + 10, b.y + wing);
    ctx.stroke();
  });
}

function drawSea() {
  const seaTop = H * 0.35;
  const seaBot = H * 0.58;
  // Sea gradient
  const grad = ctx.createLinearGradient(0, seaTop, 0, seaBot);
  grad.addColorStop(0, '#0277BD');
  grad.addColorStop(0.3, '#0288D1');
  grad.addColorStop(0.6, '#039BE5');
  grad.addColorStop(1, '#29B6F6');
  ctx.fillStyle = grad;
  ctx.fillRect(0, seaTop, W, seaBot - seaTop);

  // Waves
  for (let l = 0; l < waveLines; l++) {
    const wy = seaTop + 15 + l * ((seaBot - seaTop - 20) / waveLines);
    ctx.strokeStyle = `rgba(255,255,255,${0.3 - l * 0.04})`;
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let x = 0; x <= W; x += 5) {
      const y = wy + Math.sin((x + time * (2 + l * 0.5)) * 0.02 + l) * (4 + l * 1.5);
      if (x === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
  }

  // Foam/shore line
  const shoreY = seaBot - 5;
  ctx.fillStyle = 'rgba(255,255,255,0.6)';
  ctx.beginPath();
  ctx.moveTo(0, shoreY + 8);
  for (let x = 0; x <= W; x += 3) {
    const y = shoreY + Math.sin((x + time * 3) * 0.03) * 4 + Math.sin((x + time * 1.5) * 0.07) * 2;
    ctx.lineTo(x, y);
  }
  ctx.lineTo(W, seaBot + 5);
  ctx.lineTo(0, seaBot + 5);
  ctx.closePath();
  ctx.fill();
}

function drawBeach() {
  const beachTop = H * 0.56;
  const roadTop = H * 0.68;
  const grad = ctx.createLinearGradient(0, beachTop, 0, roadTop);
  grad.addColorStop(0, '#FFE0B2');
  grad.addColorStop(0.5, '#FFCC80');
  grad.addColorStop(1, '#FFB74D');
  ctx.fillStyle = grad;
  ctx.fillRect(0, beachTop, W, roadTop - beachTop);

  // Sand dots
  ctx.fillStyle = 'rgba(210,180,140,0.4)';
  for (let i = 0; i < 60; i++) {
    const sx = ((i * 73 + time * 0.1) % (W + 20)) - 10;
    const sy = beachTop + 10 + (i * 37 % (roadTop - beachTop - 15));
    ctx.beginPath();
    ctx.arc(sx, sy, 1.5, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawPalmTree(px, py, scale) {
  ctx.save();
  ctx.translate(px, py);
  ctx.scale(scale, scale);

  // Trunk
  ctx.strokeStyle = '#5D4037';
  ctx.lineWidth = 10;
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.quadraticCurveTo(-8, -40, -5, -80);
  ctx.quadraticCurveTo(-2, -110, 5, -130);
  ctx.stroke();

  // Trunk detail
  ctx.strokeStyle = '#4E342E';
  ctx.lineWidth = 2;
  for (let i = 0; i < 8; i++) {
    const ty = -10 - i * 15;
    ctx.beginPath();
    ctx.moveTo(-6 + i * 0.5, ty);
    ctx.lineTo(6 - i * 0.3, ty);
    ctx.stroke();
  }

  // Leaves
  const leafColors = ['#2E7D32', '#388E3C', '#43A047', '#1B5E20', '#4CAF50'];
  const sway = Math.sin(time * 0.02) * 3;
  for (let i = 0; i < 7; i++) {
    const angle = -Math.PI / 2 + (i - 3) * 0.45 + Math.sin(time * 0.015 + i) * 0.05;
    const len = 55 + Math.sin(i * 2) * 15;
    ctx.strokeStyle = leafColors[i % leafColors.length];
    ctx.lineWidth = 4;
    ctx.beginPath();
    const bx = 5, by = -130;
    const ex = bx + Math.cos(angle) * len + sway;
    const ey = by + Math.sin(angle) * len;
    const cx = bx + Math.cos(angle) * len * 0.5 + sway * 0.5;
    const cy = by + Math.sin(angle) * len * 0.3 - 15;
    ctx.moveTo(bx, by);
    ctx.quadraticCurveTo(cx, cy, ex, ey);
    ctx.stroke();

    // Leaf fronds
    ctx.strokeStyle = leafColors[(i + 2) % leafColors.length];
    ctx.lineWidth = 1.5;
    for (let f = 0.2; f < 1; f += 0.2) {
      const fx = bx + (cx - bx) * f + (ex - cx) * f * f * 0.3;
      const fy = by + (cy - by) * f + (ey - cy) * f * f * 0.3;
      ctx.beginPath();
      ctx.moveTo(fx, fy);
      ctx.lineTo(fx + Math.cos(angle + 0.8) * 10, fy + Math.sin(angle + 0.8) * 10);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(fx, fy);
      ctx.lineTo(fx + Math.cos(angle - 0.8) * 10, fy + Math.sin(angle - 0.8) * 10);
      ctx.stroke();
    }
  }

  // Coconuts
  ctx.fillStyle = '#5D4037';
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.arc(3 + i * 5 - 5, -126, 4, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.restore();
}

function drawRoad() {
  const roadTop = H * 0.68;
  const roadBot = H * 0.82;

  // Road
  const grad = ctx.createLinearGradient(0, roadTop, 0, roadBot);
  grad.addColorStop(0, '#424242');
  grad.addColorStop(0.5, '#616161');
  grad.addColorStop(1, '#424242');
  ctx.fillStyle = grad;
  ctx.fillRect(0, roadTop, W, roadBot - roadTop);

  // Road edges
  ctx.fillStyle = '#E0E0E0';
  ctx.fillRect(0, roadTop, W, 3);
  ctx.fillRect(0, roadBot - 3, W, 3);

  // Dashed center line
  const midY = (roadTop + roadBot) / 2;
  ctx.strokeStyle = '#FDD835';
  ctx.lineWidth = 3;
  ctx.setLineDash([30, 20]);
  ctx.lineDashOffset = -time * speed;
  ctx.beginPath();
  ctx.moveTo(0, midY);
  ctx.lineTo(W, midY);
  ctx.stroke();
  ctx.setLineDash([]);

  // Road markings (moving)
  markings.forEach(m => {
    m.x -= speed;
    if (m.x < -60) m.x += 20 * 120;
  });
}

function drawSidewalk() {
  const swTop = H * 0.82;
  const swBot = H * 0.88;
  ctx.fillStyle = '#BDBDBD';
  ctx.fillRect(0, swTop, W, swBot - swTop);
  // Sidewalk lines
  ctx.strokeStyle = '#9E9E9E';
  ctx.lineWidth = 1;
  for (let i = 0; i < 40; i++) {
    const lx = ((i * 80 - time * speed) % (W + 80)) - 40;
    ctx.beginPath();
    ctx.moveTo(lx, swTop);
    ctx.lineTo(lx, swBot);
    ctx.stroke();
  }
}

function drawGrass() {
  const grassTop = H * 0.88;
  const grad = ctx.createLinearGradient(0, grassTop, 0, H);
  grad.addColorStop(0, '#66BB6A');
  grad.addColorStop(0.4, '#4CAF50');
  grad.addColorStop(1, '#388E3C');
  ctx.fillStyle = grad;
  ctx.fillRect(0, grassTop, W, H - grassTop);

  // Grass blades
  for (let i = 0; i < 100; i++) {
    const gx = ((i * 47 + 13) % W);
    const gy = grassTop + (i * 31 % (H - grassTop));
    const gh = 5 + (i % 7) * 2;
    const sway2 = Math.sin(time * 0.03 + i) * 2;
    ctx.strokeStyle = i % 3 === 0 ? '#2E7D32' : '#43A047';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(gx, gy);
    ctx.lineTo(gx + sway2, gy - gh);
    ctx.stroke();
  }

  // Flowers
  const flowerColors = ['#E91E63', '#FF5722', '#9C27B0', '#FF9800', '#F44336'];
  for (let i = 0; i < 15; i++) {
    const fx = ((i * 97 + 41) % W);
    const fy = grassTop + 8 + (i * 53 % (H - grassTop - 20));
    ctx.fillStyle = flowerColors[i % flowerColors.length];
    for (let p = 0; p < 5; p++) {
      const pa = (p / 5) * Math.PI * 2 + time * 0.01;
      ctx.beginPath();
      ctx.arc(fx + Math.cos(pa) * 3, fy + Math.sin(pa) * 3, 2.5, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.fillStyle = '#FDD835';
    ctx.beginPath();
    ctx.arc(fx, fy, 2, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawBicycle(bx, by, wheelAngle, pedalAngle) {
  ctx.save();
  ctx.translate(bx, by);

  const wr = 28; // wheel radius
  const rearX = -35, rearY = 0;
  const frontX = 40, frontY = 0;

  // Wheel spokes and tires
  function drawWheel(wx, wy) {
    // Tire
    ctx.strokeStyle = '#212121';
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(wx, wy, wr, 0, Math.PI * 2);
    ctx.stroke();

    // Rim
    ctx.strokeStyle = '#757575';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(wx, wy, wr - 3, 0, Math.PI * 2);
    ctx.stroke();

    // Spokes
    ctx.strokeStyle = '#BDBDBD';
    ctx.lineWidth = 1;
    for (let s = 0; s < 8; s++) {
      const sa = wheelAngle + s * Math.PI / 4;
      ctx.beginPath();
      ctx.moveTo(wx, wy);
      ctx.lineTo(wx + Math.cos(sa) * (wr - 4), wy + Math.sin(sa) * (wr - 4));
      ctx.stroke();
    }

    // Hub
    ctx.fillStyle = '#9E9E9E';
    ctx.beginPath();
    ctx.arc(wx, wy, 4, 0, Math.PI * 2);
    ctx.fill();
  }

  drawWheel(rearX, rearY);
  drawWheel(frontX, frontY);

  // Frame
  const seatX = -15, seatY = -45;
  const handleX = 30, handleY = -50;
  const bbX = 0, bbY = -5; // bottom bracket
  const topTubeY = -38;

  ctx.strokeStyle = '#D32F2F';
  ctx.lineWidth = 4;
  ctx.lineCap = 'round';

  // Seat tube
  ctx.beginPath();
  ctx.moveTo(bbX, bbY);
  ctx.lineTo(seatX, seatY);
  ctx.stroke();

  // Down tube
  ctx.beginPath();
  ctx.moveTo(bbX, bbY);
  ctx.lineTo(frontX - 5, frontY - 15);
  ctx.stroke();

  // Top tube
  ctx.beginPath();
  ctx.moveTo(seatX, seatY + 5);
  ctx.lineTo(handleX - 5, topTubeY);
  ctx.stroke();

  // Seat stay
  ctx.strokeStyle = '#C62828';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(rearX, rearY);
  ctx.lineTo(seatX, seatY);
  ctx.stroke();

  // Chain stay
  ctx.beginPath();
  ctx.moveTo(rearX, rearY);
  ctx.lineTo(bbX, bbY);
  ctx.stroke();

  // Fork
  ctx.strokeStyle = '#D32F2F';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(frontX, frontY);
  ctx.lineTo(handleX - 3, handleY + 10);
  ctx.stroke();

  // Head tube
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(handleX - 5, topTubeY);
  ctx.lineTo(handleX - 3, handleY + 10);
  ctx.stroke();

  // Handlebars
  ctx.strokeStyle = '#424242';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(handleX - 10, handleY - 5);
  ctx.lineTo(handleX + 5, handleY - 2);
  ctx.stroke();

  // Seat
  ctx.fillStyle = '#5D4037';
  ctx.beginPath();
  ctx.ellipse(seatX, seatY - 4, 12, 5, -0.1, 0, Math.PI * 2);
  ctx.fill();

  // Chain ring
  ctx.strokeStyle = '#757575';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(bbX, bbY, 10, 0, Math.PI * 2);
  ctx.stroke();

  // Pedals and cranks
  const crankLen = 18;
  const pedal1X = bbX + Math.cos(pedalAngle) * crankLen;
  const pedal1Y = bbY + Math.sin(pedalAngle) * crankLen;
  const pedal2X = bbX + Math.cos(pedalAngle + Math.PI) * crankLen;
  const pedal2Y = bbY + Math.sin(pedalAngle + Math.PI) * crankLen;

  ctx.strokeStyle = '#616161';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(bbX, bbY);
  ctx.lineTo(pedal1X, pedal1Y);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(bbX, bbY);
  ctx.lineTo(pedal2X, pedal2Y);
  ctx.stroke();

  // Pedal platforms
  ctx.fillStyle = '#424242';
  ctx.save();
  ctx.translate(pedal1X, pedal1Y);
  ctx.fillRect(-6, -2, 12, 4);
  ctx.restore();
  ctx.save();
  ctx.translate(pedal2X, pedal2Y);
  ctx.fillRect(-6, -2, 12, 4);
  ctx.restore();

  ctx.restore();
}

function drawPelican(px, py, pedalAngle) {
  ctx.save();
  ctx.translate(px, py);

  const bodyBob = Math.sin(time * 0.08) * 2;
  const legCycle = pedalAngle;

  // Legs (connecting to pedals)
  const bbX = 0, bbY = -5;
  const crankLen = 18;
  const hipX = -8, hipY = -50 + bodyBob;

  // Leg to pedal 1
  const p1x = bbX + Math.cos(legCycle) * crankLen;
  const p1y = bbY + Math.sin(legCycle) * crankLen;
  ctx.strokeStyle = '#FF8F00';
  ctx.lineWidth = 5;
  ctx.lineCap = 'round';

  // Right leg
  const kneeR = getKnee(hipX, hipY, p1x, p1y, 25, 25, 1);
  ctx.beginPath();
  ctx.moveTo(hipX, hipY);
  ctx.lineTo(kneeR.x, kneeR.y);
  ctx.lineTo(p1x, p1y);
  ctx.stroke();

  // Left leg
  const p2x = bbX + Math.cos(legCycle + Math.PI) * crankLen;
  const p2y = bbY + Math.sin(legCycle + Math.PI) * crankLen;
  const kneeL = getKnee(hipX + 3, hipY, p2x, p2y, 25, 25, -1);
  ctx.beginPath();
  ctx.moveTo(hipX + 3, hipY);
  ctx.lineTo(kneeL.x, kneeL.y);
  ctx.lineTo(p2x, p2y);
  ctx.stroke();

  // Feet on pedals
  ctx.fillStyle = '#FF8F00';
  drawFoot(p1x, p1y);
  drawFoot(p2x, p2y);

  // Body
  const bodyX = -10, bodyY = -65 + bodyBob;
  ctx.fillStyle = '#F5F5F5';
  ctx.beginPath();
  ctx.ellipse(bodyX, bodyY, 22, 30, 0.15, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = '#E0E0E0';
  ctx.lineWidth = 1;
  ctx.stroke();

  // Wing
  const wingFlap = Math.sin(time * 0.06) * 5;
  ctx.fillStyle = '#EEEEEE';
  ctx.beginPath();
  ctx.moveTo(bodyX - 5, bodyY - 10);
  ctx.quadraticCurveTo(bodyX - 30, bodyY - 5 + wingFlap, bodyX - 25, bodyY + 15 + wingFlap);
  ctx.quadraticCurveTo(bodyX - 10, bodyY + 20, bodyX + 5, bodyY + 10);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#BDBDBD';
  ctx.lineWidth = 1;
  ctx.stroke();

  // Wing feather details
  ctx.strokeStyle = '#BDBDBD';
  ctx.lineWidth = 0.8;
  ctx.beginPath();
  ctx.moveTo(bodyX - 8, bodyY);
  ctx.quadraticCurveTo(bodyX - 20, bodyY + 2 + wingFlap * 0.5, bodyX - 22, bodyY + 12 + wingFlap);
  ctx.stroke();

  // Neck
  const neckTopX = bodyX + 15, neckTopY = bodyY - 55;
  ctx.fillStyle = '#F5F5F5';
  ctx.strokeStyle = '#F5F5F5';
  ctx.lineWidth = 14;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(bodyX + 5, bodyY - 22);
  ctx.quadraticCurveTo(bodyX + 25, bodyY - 40, neckTopX, neckTopY);
  ctx.stroke();

  // Neck outline
  ctx.strokeStyle = '#E0E0E0';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(bodyX - 1, bodyY - 22);
  ctx.quadraticCurveTo(bodyX + 18, bodyY - 42, neckTopX - 6, neckTopY - 2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(bodyX + 12, bodyY - 20);
  ctx.quadraticCurveTo(bodyX + 32, bodyY - 38, neckTopX + 7, neckTopY);
  ctx.stroke();

  // Head
  const headX = neckTopX, headY = neckTopY;
  ctx.fillStyle = '#F5F5F5';
  ctx.beginPath();
  ctx.ellipse(headX, headY, 14, 12, 0.1, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = '#E0E0E0';
  ctx.lineWidth = 1;
  ctx.stroke();

  // Eye
  ctx.fillStyle = '#212121';
  ctx.beginPath();
  ctx.arc(headX + 6, headY - 4, 3, 0, Math.PI * 2);
  ctx.fill();
  // Eye highlight
  ctx.fillStyle = '#FFF';
  ctx.beginPath();
  ctx.arc(headX + 7, headY - 5, 1.2, 0, Math.PI * 2);
  ctx.fill();

  // Beak (long pelican beak)
  const beakLen = 45;
  ctx.fillStyle = '#FF8F00';
  ctx.beginPath();
  ctx.moveTo(headX + 12, headY - 5);
  ctx.lineTo(headX + beakLen, headY - 2);
  ctx.lineTo(headX + beakLen - 3, headY + 2);
  ctx.lineTo(headX + 12, headY + 4);
  ctx.closePath();
  ctx.fill();

  // Beak lower (pouch)
  ctx.fillStyle = '#FFB74D';
  ctx.beginPath();
  ctx.moveTo(headX + 12, headY + 4);
  ctx.quadraticCurveTo(headX + 25, headY + 18, headX + beakLen - 3, headY + 2);
  ctx.lineTo(headX + 12, headY + 4);
  ctx.closePath();
  ctx.fill();

  // Beak line
  ctx.strokeStyle = '#E65100';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(headX + 12, headY);
  ctx.lineTo(headX + beakLen, headY);
  ctx.stroke();

  // Beak tip
  ctx.fillStyle = '#EF6C00';
  ctx.beginPath();
  ctx.moveTo(headX + beakLen, headY - 2);
  ctx.lineTo(headX + beakLen + 4, headY);
  ctx.lineTo(headX + beakLen, headY + 2);
  ctx.closePath();
  ctx.fill();

  // Head crest/tuft
  ctx.strokeStyle = '#F5F5F5';
  ctx.lineWidth = 2;
  for (let i = 0; i < 4; i++) {
    const ca = -Math.PI * 0.6 - i * 0.15;
    ctx.beginPath();
    ctx.moveTo(headX - 5, headY - 8);
    ctx.lineTo(headX - 5 + Math.cos(ca) * (10 + i * 3), headY - 8 + Math.sin(ca) * (10 + i * 3));
    ctx.stroke();
  }

  // Arms/wings gripping handlebars
  const handleX = 30, handleY = -50;
  ctx.strokeStyle = '#F5F5F5';
  ctx.lineWidth = 6;
  ctx.lineCap = 'round';
  // Right arm
  ctx.beginPath();
  ctx.moveTo(bodyX + 15, bodyY - 15);
  ctx.quadraticCurveTo(bodyX + 30, bodyY - 25, handleX + px > px ? handleX : handleX, handleY);
  ctx.stroke();

  // Hands
  ctx.fillStyle = '#EEEEEE';
  ctx.beginPath();
  ctx.arc(handleX, handleY, 5, 0, Math.PI * 2);
  ctx.fill();

  ctx.restore();
}

function drawFoot(fx, fy) {
  ctx.beginPath();
  ctx.moveTo(fx - 3, fy);
  ctx.lineTo(fx + 10, fy + 2);
  ctx.lineTo(fx + 8, fy + 5);
  ctx.lineTo(fx - 3, fy + 3);
  ctx.closePath();
  ctx.fill();
  // Webbed foot lines
  ctx.strokeStyle = '#EF6C00';
  ctx.lineWidth = 0.5;
  ctx.beginPath();
  ctx.moveTo(fx, fy + 1);
  ctx.lineTo(fx + 8, fy + 2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(fx, fy + 2);
  ctx.lineTo(fx + 7, fy + 4);
  ctx.stroke();
}

function getKnee(hx, hy, px, py, thighLen, shinLen, dir) {
  const dx = px - hx, dy = py - hy;
  const dist = Math.sqrt(dx * dx + dy * dy);
  const clampedDist = Math.min(dist, thighLen + shinLen - 1);
  const a = Math.atan2(dy, dx);
  const cosAngle = (thighLen * thighLen + clampedDist * clampedDist - shinLen * shinLen) / (2 * thighLen * clampedDist);
  const clampedCos = Math.max(-1, Math.min(1, cosAngle));
  const kneeAngle = a - dir * Math.acos(clampedCos);
  return {
    x: hx + Math.cos(kneeAngle) * thighLen,
    y: hy + Math.sin(kneeAngle) * thighLen
  };
}

// Sailboat
let sailboatX = W + 100;
function drawSailboat() {
  sailboatX -= 0.5;
  if (sailboatX < -100) sailboatX = W + 200 + Math.random() * 300;

  const sbY = H * 0.4;
  const bob = Math.sin(time * 0.03) * 3;

  ctx.save();
  ctx.translate(sailboatX, sbY + bob);

  // Hull
  ctx.fillStyle = '#5D4037';
  ctx.beginPath();
  ctx.moveTo(-20, 0);
  ctx.lineTo(25, 0);
  ctx.lineTo(20, 8);
  ctx.lineTo(-15, 8);
  ctx.closePath();
  ctx.fill();

  // Mast
  ctx.strokeStyle = '#4E342E';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(5, 0);
  ctx.lineTo(5, -35);
  ctx.stroke();

  // Sail
  ctx.fillStyle = '#FFFFFF';
  ctx.globalAlpha = 0.9;
  ctx.beginPath();
  ctx.moveTo(5, -33);
  ctx.lineTo(5, -2);
  ctx.lineTo(22, -2);
  ctx.closePath();
  ctx.fill();
  ctx.globalAlpha = 1;

  ctx.restore();
}

function draw() {
  ctx.clearRect(0, 0, W, H);

  drawSky();
  drawSun();
  drawClouds();
  drawBirds();
  drawSea();
  drawSailboat();
  drawBeach();

  // Palm trees behind road
  const roadTop = H * 0.68;
  palms.forEach(p => {
    const treeX = ((p.x - time * speed * 0.8) % (W + 200));
    const adjustedX = treeX < -100 ? treeX + W + 200 : treeX;
    drawPalmTree(adjustedX, roadTop - 5, p.scale);
  });

  drawRoad();
  drawSidewalk();
  drawGrass();

  // Bicycle and pelican position
  const bikeX = W * 0.38;
  const bikeY = H * 0.68 + (H * 0.82 - H * 0.68) * 0.65;
  const wheelAngle = time * 0.08;
  const pedalAngle = time * 0.08;

  // Shadow
  ctx.fillStyle = 'rgba(0,0,0,0.15)';
  ctx.beginPath();
  ctx.ellipse(bikeX + 2, bikeY + 30, 50, 8, 0, 0, Math.PI * 2);
  ctx.fill();

  drawBicycle(bikeX, bikeY, wheelAngle, pedalAngle);
  drawPelican(bikeX, bikeY, pedalAngle);

  // Speed lines
  ctx.strokeStyle = 'rgba(200,200,200,0.3)';
  ctx.lineWidth = 1;
  for (let i = 0; i < 5; i++) {
    const lx = bikeX - 70 - Math.random() * 30;
    const ly = bikeY - 20 + i * 12;
    const ll = 15 + Math.random() * 20;
    if (Math.random() > 0.5) {
      ctx.beginPath();
      ctx.moveTo(lx, ly);
      ctx.lineTo(lx - ll, ly);
      ctx.stroke();
    }
  }

  time++;
  requestAnimationFrame(draw);
}

draw();
